package cc.thonly.reverie_dreams.paper.world;

import com.google.gson.JsonArray;
import com.google.gson.JsonParser;
import org.junit.jupiter.api.Test;

import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.HashMap;
import java.util.HexFormat;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

import static org.junit.jupiter.api.Assertions.*;

class GensokyoOreGenerationTest {
    @Test void ellipsoidsAndAirExposureMatchActualTargetOreFeatureBytecode() throws Exception {
        // Generated by executing the runtime26.1.2 OreFeature.class itself,
        // with only its world/block storage replaced by minimal data holders.
        // RNG and Mth are the real target classes. No server or NMS test dependency is required here.
        for (var element : resource("native-ore-goldens.json")) {
            var expected = element.getAsJsonObject();
            var random = new GensokyoFeatureRandom(expected.get("seed").getAsLong());
            var region = new MemoryRegion(expected.get("cave").getAsBoolean());
            var config = new GensokyoOreFeatures.Feature(expected.get("size").getAsInt(), expected.get("discard").getAsFloat(),
                    List.of(new GensokyoOreFeatures.Target("minecraft:block_match", "stone", "ore")));
            GensokyoOreGenerator.placeVein(random, config, 8, 900, 8, region);
            assertEquals(expected.get("count").getAsInt(), region.writes.size(), expected.toString());
            assertEquals(expected.get("sha256").getAsString(), digest(region.writes), expected.toString());
            assertEquals(expected.get("next_long").getAsLong(), random.nextLong(), "Exact RNG consumption: " + expected);
        }
    }

    @Test void everyBandMatchesUnchangedOriginalSamplingWithNativeWorldgenRandom() throws Exception {
        for (var element : resource("source-band-goldens.json")) {
            var expected = element.getAsJsonObject();
            var band = GensokyoOreGenerator.BANDS.stream().filter(b -> b.name().equals(expected.get("band").getAsString())).findFirst().orElseThrow();
            var random = new GensokyoFeatureRandom(0);
            long seed = random.decorationSeed(expected.get("world_seed").getAsLong(), expected.get("chunk_x").getAsInt() << 4, expected.get("chunk_z").getAsInt() << 4);
            assertEquals(expected.get("decoration_seed").getAsLong(), seed);
            random.bandSeed(seed, band.name());
            assertEquals(expected.get("feature").getAsString(), band.feature());
            assertEquals(expected.get("count").getAsInt(), band.count(random), band.name());
            assertEquals(expected.get("local_x").getAsInt(), random.nextInt(16));
            assertEquals(expected.get("local_z").getAsInt(), random.nextInt(16));
            assertEquals(expected.get("sample_y").getAsInt(), band.y(random, 1063, 1024), band.name());
            assertEquals(expected.get("next_long").getAsLong(), random.nextLong(), band.name());
        }
    }

    @Test void oreBiomeRestrictionsUseNativeThreeDimensionalZoomSelection() throws Exception {
        for (var element : resource("native-biome-goldens.json")) {
            var expected = element.getAsJsonObject();
            var sampling = new GensokyoBiomeSampling(expected.get("seed").getAsLong());
            var quart = sampling.quart(expected.get("x").getAsInt(), expected.get("y").getAsInt(), expected.get("z").getAsInt());
            assertEquals(expected.get("quart").getAsString(), quart.x() + "," + quart.y() + "," + quart.z(), expected.toString());
        }
    }

    @Test void envelopesProtectSurfaceGlobalFloorMapEdgesAndAuthoredNeighborWrites() throws Exception {
        var catalog = GensokyoOreFeatures.bundled();
        var normal = new GensokyoOreGenerator(columns("minecraft:grass_block", Map.of()), catalog);
        assertEquals(704, normal.miningFloor());
        assertFalse(normal.fitsVein(6400, 747, 5120, 17));
        assertTrue(normal.fitsVein(6400, 748, 5120, 17));
        assertTrue(normal.fitsVein(6400, 1054, 5120, 17));
        assertFalse(normal.fitsVein(6400, 1055, 5120, 17));
        assertFalse(normal.fitsVein(0, 900, 5120, 17));
        var authored = new GensokyoMap.Override(6405, 902, 5120, "minecraft:air");
        var protectedTerrain = new GensokyoOreGenerator(columns("minecraft:grass_block", Map.of(GensokyoMap.chunkKey(6405 >> 4, 5120 >> 4), List.of(authored))), catalog);
        assertFalse(protectedTerrain.fitsVein(6400, 900, 5120, 17));
        assertTrue(protectedTerrain.fitsVein(6398, 900, 5120, 17));
        assertEquals(1056, new GensokyoOreGenerator(columns("minecraft:water", Map.of()), catalog).solidTop(6400, 5120));
        assertEquals(967, new GensokyoOreGenerator(columns("minecraft:lava", Map.of()), catalog).solidTop(6400, 5120));
        assertEquals(GensokyoMap.NO_SURFACE, new GensokyoOreGenerator(columns("minecraft:air", Map.of()), catalog).solidTop(6400, 5120));
    }

    @Test void allTwentyBandsUseLockedTargetsBiomeRestrictionsAndRepeatableContinuousVeins() throws Exception {
        var catalog = GensokyoOreFeatures.bundled();
        assertEquals(20, GensokyoOreGenerator.BANDS.size());
        assertEquals(17, catalog.features().size());
        assertEquals(4, catalog.states().stream().filter(s -> s.startsWith("reverie_dreams:")).count());
        assertEquals(15, catalog.features().get("reverie_dreams:overworld_silver_ore").size());
        assertEquals(.32F, catalog.features().get("reverie_dreams:overworld_orb_ore").discardChance());
        var generator = new GensokyoOreGenerator(columns("minecraft:grass_block", Map.of()), catalog);
        var emerald = GensokyoOreGenerator.BANDS.stream().filter(b -> b.name().equals("emerald_highland")).findFirst().orElseThrow();
        var badlands = GensokyoOreGenerator.BANDS.stream().filter(b -> b.name().equals("gold_badlands")).findFirst().orElseThrow();
        assertTrue(generator.allows(emerald, "minecraft:stony_peaks"));
        assertFalse(generator.allows(emerald, "minecraft:plains"));
        assertTrue(generator.allows(badlands, "minecraft:badlands"));
        assertFalse(generator.allows(badlands, "minecraft:forest"));
        var first = new MemoryRegion(false);
        var second = new MemoryRegion(false);
        generator.populate(123456789L, 400, 320, first);
        generator.populate(123456789L, 400, 320, second);
        assertEquals(first.writes, second.writes);
        assertTrue(first.writes.values().stream().anyMatch("reverie_dreams:silver_ore"::equals));
        assertTrue(first.writes.values().stream().anyMatch("reverie_dreams:orb_ore"::equals));
        assertTrue(first.writes.size() > 50);
        for (String coordinate : first.writes.keySet()) {
            int y = Integer.parseInt(coordinate.split(",")[1]);
            assertTrue(y >= 704 && y <= 1059, coordinate);
        }
    }

    @Test void originalBaseOrePlacementsRetainFullHeightAndLowWorldAnchors() throws Exception {
        var catalog = GensokyoOreFeatures.bundled();
        var generator = new GensokyoOreGenerator(columns("minecraft:grass_block", Map.of()), catalog);
        var combined = new HashMap<String, String>();
        for (int cx = 398; cx <= 402; cx++) {
            var region = new MemoryRegion(false);
            generator.populateSourcePlacements(123456789L, cx, 320, region);
            combined.putAll(region.writes);
        }
        assertTrue(combined.values().stream().anyMatch("reverie_dreams:silver_ore"::equals));
        assertTrue(combined.values().stream().anyMatch("reverie_dreams:orb_ore"::equals));
        assertTrue(combined.entrySet().stream().anyMatch(e -> e.getValue().equals("reverie_dreams:orb_ore") && Integer.parseInt(e.getKey().split(",")[1]) < 81));
        assertTrue(combined.keySet().stream().map(c -> Integer.parseInt(c.split(",")[1])).anyMatch(y -> y < 704));
    }

    private static JsonArray resource(String name) throws Exception {
        try (var reader = new InputStreamReader(GensokyoOreGenerationTest.class.getResourceAsStream("/worldgen/" + name), StandardCharsets.UTF_8)) {
            return JsonParser.parseReader(reader).getAsJsonArray();
        }
    }
    private static String digest(Map<String, String> values) throws Exception {
        var sha = MessageDigest.getInstance("SHA-256");
        for (var entry : new TreeMap<>(values).entrySet()) sha.update((entry.getKey() + "=" + entry.getValue() + "\n").getBytes(StandardCharsets.UTF_8));
        return HexFormat.of().formatHex(sha.digest());
    }
    private static GensokyoColumns columns(String surface, Map<Long, List<GensokyoMap.Override>> underground) {
        var map = new GensokyoMap(1, 2, "reverie_dreams:gensokyo", 12800, 10240, 0, 0, 0, 1536, 1024, 3, 0,
                new GensokyoMap.Spawn(6400, 1064, 5120, 0, 0), List.of("minecraft:plains"), List.of(surface),
                "heightmap.delta.gz", "biomes.pal4.gz", "surfaces.pal4.gz", null, 0, underground);
        return new GensokyoColumns() {
            public GensokyoMap map() { return map; }
            public int heightAt(int x, int z) { return map.contains(x, z) ? 1063 : GensokyoMap.NO_SURFACE; }
            public int biomeAt(int x, int z) { return 0; }
            public String surfaceAt(int x, int z) { return map.contains(x, z) ? surface : "minecraft:air"; }
        };
    }
    private static final class MemoryRegion implements GensokyoOreGenerator.Region {
        final Map<String, String> writes = new HashMap<>();
        final boolean cave;
        MemoryRegion(boolean cave) { this.cave = cave; }
        public String state(int x, int y, int z) {
            if (y < 0 || y > 1063 || cave && x == 9 && y >= 898 && y <= 904) return "air";
            return writes.getOrDefault(x + "," + y + "," + z, "stone");
        }
        public void set(int x, int y, int z, String state) { writes.put(x + "," + y + "," + z, state); }
        public boolean matches(GensokyoOreFeatures.Target target, String current) { return current.equals("stone"); }
        public boolean air(int x, int y, int z) { return state(x, y, z).equals("air"); }
        public boolean canWrite(int x, int y, int z) { return y >= 0 && y < 1536; }
        public int oceanFloor(int x, int z) { return 1064; }
        public String biome(int x, int y, int z) { return "minecraft:plains"; }
    }
}
